def load_credentials(filepath):
    creds = []
    try:
        with open(filepath, 'r') as f:
            for line in f:
                if ':' in line:
                    email, password = line.strip().split(':', 1)
                    creds.append((email, password))
    except FileNotFoundError:
        print(f"Error: File {filepath} not found.")
    return creds

